    _dyn = ((_scale * float(period)).round().clip(2, 500).fillna(float(period))).astype(int).to_numpy()
    if adapt:
        _eff = _dyn
    else:
        _eff = np.full(n, int(period), dtype=int)
    _atr = (high - low).rolling(14, min_periods=1).mean().bfill().ffill().fillna(1e-9)
    _ma = close.rolling(int(period), min_periods=1).mean()
    _sd = close.rolling(int(period), min_periods=2).std().bfill().ffill().fillna(1e-9)
    _sk = close.rolling(int(period), min_periods=5).skew().fillna(0.0)
    _c = close.to_numpy(dtype=float)
    _m = _ma.to_numpy(dtype=float)
    _s = _sd.to_numpy(dtype=float)
    _k = np.clip(_sk.to_numpy(dtype=float), -2.0, 2.0)
    _width = _s * (float(2.75) + 0.25 * _k) + 1e-12
    result = (_c - (_m - _width)) / (2.0 * _width) - 0.5
    out = pd.Series(result, index=df.index, name="v_tide_osc_cascade")
    out = out.replace([np.inf, -np.inf], np.nan).ffill().bfill().fillna(0.0)
    return out

